// UGC NET Physical Education — Paper II question papers, 2009 to 2013 (eight booklets).
// HONESTY NOTES (shown to users in the app, repeated here for maintainers):
//  * Question text is transcribed from the English side of each bilingual booklet.
//  * No official answer key was supplied with these papers. Every answer here is a PROVISIONAL KEY
//    compiled from standard textbook knowledge and has not been reviewed by a subject expert.
//  * Questions whose answer could not be settled with confidence, and questions whose layout could
//    not be transcribed reliably (most matching-type and assertion–reason items), are left OUT.
//    Each paper records how many questions it had (50) and how many are included.
//  * The question numbers stored here (paperNo) are our own running numbers within each paper, not
//    the numbers printed on the booklet.
const NET_PAPER_QUESTIONS = {};
function pqn(set, prefix, year, n, subject, topic, question, options, correct, explanation){
  NET_PAPER_QUESTIONS[set].push({
    id: prefix + "-" + String(n).padStart(3, "0"),
    exam: ["UGC NET"],
    subject, topic,
    difficulty: "Moderate", type: "MCQ",
    year, paperNo: n,
    question, options, correctIndex: correct, explanation,
    source: "UGC NET Physical Education, Paper II, " + SETLABEL[set] + " — provisional key",
    tags: ["past-paper", "provisional-key"],
  });
}

const SETLABEL = {"S13": "S-47-13 (2013)", "D12": "D-47-12 (December 2012)", "J12": "J-47-12 (June 2012)", "D11": "D-47-11 (December 2011)", "J11": "J-47-11 (June 2011)", "J10": "J-47-10 (June 2010)", "D09": "D-47-09 (December 2009)", "J09": "J-47-09 (June 2009)"};

