pqn("J09","N09J",2009,2,"Foundations of Physical Education","International charters","Physical education is a fundamental right of every citizen, is part of which charter ?",["UNESCO", "WHO", "UNO", "UGC"],0,"The UNESCO International Charter of Physical Education and Sport (1978) declares access to physical education a fundamental right of every human being.");
pqn("J09","N09J",2009,3,"Olympic Movement","Olympic history","Identify the correct order in which the following Olympics were held:",["Sydney, Athens, Beijing", "Seoul, Moscow, Los Angeles", "Moscow, Los Angeles, Montreal", "Atlanta, Barcelona, Montreal"],0,"Sydney 2000, Athens 2004, Beijing 2008.");
pqn("J09","N09J",2009,4,"Olympic Movement","Beijing 2008","Identify the correct order of the top three gold-medal winning countries at the Beijing Olympics.",["China, America, Russia", "China, Korea, England", "U.S.A., China, USSR", "China, Russia, Australia"],0,"China topped the Beijing 2008 gold-medal table with 51 golds, ahead of the USA (36) and Russia (23).");
pqn("J09","N09J",2009,5,"Exercise Physiology","Muscle contraction","The proteins involved in muscular contraction are:",["Actin", "Myosin", "Both Actin and Myosin", "None of these"],2,"Both actin and myosin take part in contraction (sliding-filament mechanism).");
pqn("J09","N09J",2009,6,"Exercise Physiology","Energy systems","Lactic acid is the by-product of:",["Aerobic Metabolism", "Protein Metabolism", "Oxidation", "Anaerobic Metabolism"],3,"Lactic acid is the by-product of anaerobic glycolysis.");
pqn("J09","N09J",2009,7,"Nutrition","Nutrients","Which of the following is essential for repair of the wear and tear of muscles in the body?",["Vitamins", "Minerals", "Proteins", "Carbohydrates"],2,"Protein is needed to repair the wear and tear of muscles.");
pqn("J09","N09J",2009,8,"Exercise Physiology","Fatigue","Which condition occurs due to accumulation of lactic acid?",["Freshness", "Fatigue", "Relaxation", "None of the above"],1,"Accumulation of lactic acid contributes to muscular fatigue.");
pqn("J09","N09J",2009,9,"Exercise Physiology","Muscle structure","A sarcomere is the area:",["Between two I Bands", "Between two A Bands", "Between two Z lines", "Between I and A Bands"],2,"A sarcomere is the contractile unit lying between two Z-lines.");
pqn("J09","N09J",2009,10,"Physiology","Blood","The main function of WBC is:",["To fight against the infection", "To transport nutrient", "To transport oxygen", "To remove waste products"],0,"White blood cells defend the body against infection.");
pqn("J09","N09J",2009,11,"Physiology","Respiration","Blood is oxygenated in :",["Mussels", "Lungs", "Heart", "Brain"],1,"Blood is oxygenated in the lungs.");
pqn("J09","N09J",2009,12,"Sports Psychology","Placebo effect","A physiological improvement brought about by a psychological mechanism is the:",["Placebo effect", "Hypothesis", "Motivation", "Ergometry"],0,"A physiological improvement produced by belief or expectation rather than by any active treatment is the placebo effect.");
pqn("J09","N09J",2009,13,"Sports Psychology","Anxiety","An inborn general tendency to be anxious is an example of:",["Trait anxiety", "State anxiety", "Conflict", "None of the these"],0,"An inborn, general tendency to be anxious is trait anxiety; state anxiety is anxiety in a particular situation.");
pqn("J09","N09J",2009,14,"Sports Management","Leadership styles","The leader who allows complete freedom in decision making and does not participate in the group activities is:",["Democratic", "Autocratic", "Laissez faire", "Dictator"],2,"A laissez-faire leader gives the group complete freedom and takes little part in its activities.");
pqn("J09","N09J",2009,15,"Sports Management","Tournaments","Total number of matches in a league tournament of 8 teams will be :",["12", "28", "25", "15"],1,"A league (round-robin) of n teams needs n(n − 1)/2 matches: 8 × 7 ÷ 2 = 28.");
pqn("J09","N09J",2009,16,"Test, Measurement & Evaluation","Fitness tests","The Sargent jump measures:",["Explosive Leg Strength", "Explosive Shoulder Strength", "Agility", "Flexibility"],0,"The Sargent jump (vertical jump) measures explosive leg strength.");
pqn("J09","N09J",2009,17,"Test, Measurement & Evaluation","Fitness tests","Cooper's test is a measure of:",["Aerobic Capacity", "Strength", "Anaerobic Capacity", "None of the above"],0,"Cooper's 12-minute test estimates aerobic capacity (VO2 max).");
pqn("J09","N09J",2009,18,"Test, Measurement & Evaluation","Sociometry","A sociogram illustrates the pattern of relationship among:",["Employees in a big organization", "Members of social groups", "Teaching standard of an institution", "Problems faced by a researcher"],1,"A sociogram maps the pattern of relationships among the members of a social group.");
pqn("J09","N09J",2009,19,"Research Methodology","Limitations","Factors beyond the control of the researcher are called:",["Experimental variables", "Limitations", "Critical factors", "All of the above"],1,"Factors beyond the researcher's control are limitations of the study.");
pqn("J09","N09J",2009,20,"Statistics","Variability","The most reliable measure of variability is :",["Two Mean", "Standard Deviation", "Quartile Deviation", "Mode"],1,"The standard deviation is the most reliable (stable) measure of variability.");
pqn("J09","N09J",2009,21,"Test, Measurement & Evaluation","Fitness tests","The Kraus–Weber test measures:",["Motor Ability", "Motor Fitness", "Minimum Muscular Fitness", "Physical Fitness"],2,"The Kraus–Weber test checks minimum muscular fitness (strength and flexibility of the trunk and legs).");
pqn("J09","N09J",2009,22,"Test, Measurement & Evaluation","Flexibility","Hamstring and back flexibility is measured by:",["Sit and reach test", "Bass stick test", "Boomrang test", "None of the above"],0,"The sit-and-reach test measures hamstring and lower-back flexibility.");
pqn("J09","N09J",2009,23,"Test, Measurement & Evaluation","Evaluation","Evaluation used by the teacher throughout the instructional stages of a unit of learning is called:",["Summative evaluation", "Subjective evaluation", "Formative evaluation", "All the above"],2,"Formative evaluation is carried out during instruction to give feedback; summative evaluation comes at the end.");
